type Seq = { seqId: string; pos: number; size: number };
const groups = new Map<string, (Buffer | undefined)[]>();

function onPart(h: Seq, body: Buffer): Buffer | null {
  const parts = groups.get(h.seqId) ?? Array(h.size).fill(undefined);
  parts[h.pos - 1] = body;
  groups.set(h.seqId, parts);
  return parts.every(Boolean) ? Buffer.concat(parts as Buffer[]) : null;
}
